"""Lay students out in rows, sorted by last name."""

from typing import List

def _sort_key(student):
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())

def _check(students, seats):
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def _chunks(items, size):
    starts = range(0, len(items), size)
    return [items[start:start + size] for start in starts]

def _format_row(number, group):
    names = " | ".join(stud.display_name for stud in group)
    return f"Row {number}: {names}"

def _render(rows):
    lines = []
    for index, group in enumerate(rows, 1):
        lines.append(_format_row(index, group))
    return lines

# ---
def seating_rows(students, seats) -> List[str]:
    """One text line per row of seats."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    return _render(_chunks(ordered, seats))

