# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def make(last, first):
    return Student(last + first, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorts_by_last_name_and_fills_rows(self):
        names = ["Halloway", "Dunmere", "Abbot"]
        crowd = [make(name, "X") for name in names]
        self.assertEqual(seating_rows(crowd, 2), [
            "Row 1: Abbot, X | Dunmere, X",
            "Row 2: Halloway, X"
        ])

    def test_ties_break_on_first_name(self):
        crowd = [make("Lee", "Zed"), make("Lee", "Amy")]
        rows = seating_rows(crowd, 5)
        want = "Row 1: Lee, Amy | Lee, Zed"
        self.assertEqual(rows, [want])

    def test_sorting_ignores_case(self):
        crowd = [make("zane", "Al"), make("Young", "Bo")]
        rows = seating_rows(crowd, 1)
        self.assertEqual(rows[0], "Row 1: Young, Bo")

    def test_input_is_not_modified(self):
        crowd = [make("Zed", "A"), make("Abe", "B")]
        seating_rows(crowd, 2)
        self.assertEqual(crowd[0].last_name, "Zed")

    def test_bad_seat_counts_raise(self):
        crowd = [make("Abe", "B")]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(crowd, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
